ALTER TABLE public.work_entries ADD CONSTRAINT chk_periodo_numero CHECK (((periodo_numero IS NULL) OR ((periodo_numero >= 1) AND (periodo_numero <=
CASE periodo_tipo
    WHEN 'dia'::text THEN 31
    WHEN 'semana'::text THEN 53
    WHEN 'quinzena'::text THEN 24
    WHEN 'mes'::text THEN 12
    ELSE 366
END))));
